import React, { useState, useEffect } from 'react';
import Papa from 'papaparse';
import { Search, Download, TrendingUp } from 'lucide-react';

const PrescriptionTable = () => {
  const [allocations, setAllocations] = useState([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [loading, setLoading] = useState(true);

  // Load and parse the allocation.csv file generated by the SciPy script
  useEffect(() => {
    const fetchAllocations = async () => {
      try {
        // Adjust this path based on where your app serves public static files
        const response = await fetch('/data/processed/allocation.csv');
        const csvText = await response.text();
        
        Papa.parse(csvText, {
          header: true,
          dynamicTyping: true,
          complete: (results) => {
            setAllocations(results.data.filter(row => row.customer_id)); // Filter empty rows
            setLoading(false);
          }
        });
      } catch (error) {
        console.error("Error loading allocations:", error);
        setLoading(false);
      }
    };

    fetchAllocations();
  }, []);

  const totalSpend = allocations.reduce((sum, row) => sum + (row.cost || 0), 0);
  const totalLift = allocations.reduce((sum, row) => sum + (row.predicted_effect || 0), 0);
  
  const filteredData = allocations.filter(row => 
    row.customer_id?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  return (
    <div className="p-8 w-full mx-auto bg-gray-50 rounded-lg">
      <div className="mb-8">
        <h1 className="text-3xl font-bold text-gray-900 mb-2">Prescription Engine</h1>
        <p className="text-gray-600">Mathematically optimal discount allocations based on predicted ITE.</p>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-3 gap-6 mb-8">
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
          <p className="text-sm font-medium text-gray-500 mb-1">Total Budget Allocated</p>
          <p className="text-3xl font-bold text-gray-900">${totalSpend.toLocaleString()}</p>
        </div>
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
          <p className="text-sm font-medium text-gray-500 mb-1">Customers Targeted</p>
          <p className="text-3xl font-bold text-gray-900">{allocations.length.toLocaleString()}</p>
        </div>
        <div className="bg-white p-6 rounded-lg shadow-sm border border-gray-200">
          <p className="text-sm font-medium text-gray-500 mb-1">Predicted Extra Repeats</p>
          <div className="flex items-center">
            <p className="text-3xl font-bold text-green-600 mr-2">{totalLift.toFixed(1)}</p>
            <TrendingUp className="text-green-600 w-6 h-6" />
          </div>
        </div>
      </div>

      <div className="bg-white rounded-lg shadow-sm border border-gray-200 overflow-hidden">
        <div className="p-4 border-b border-gray-200 flex justify-between items-center bg-white">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 transform -translate-y-1/2 text-gray-400 w-5 h-5" />
            <input
              type="text"
              placeholder="Search Customer ID..."
              className="pl-10 pr-4 py-2 border border-gray-300 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 w-64"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
          <button className="flex items-center px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 transition-colors">
            <Download className="w-4 h-4 mr-2" />
            Export CSV
          </button>
        </div>

        <div className="overflow-x-auto">
          <table className="w-full text-left border-collapse">
            <thead>
              <tr className="bg-gray-50 text-gray-600 text-sm border-b border-gray-200">
                <th className="px-6 py-4 font-semibold">Customer ID</th>
                <th className="px-6 py-4 font-semibold">Allocated Discount</th>
                <th className="px-6 py-4 font-semibold">Cost</th>
                <th className="px-6 py-4 font-semibold">Predicted Lift (Repeats)</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-gray-200">
              {loading ? (
                <tr>
                  <td colSpan="4" className="px-6 py-8 text-center text-gray-500">
                    Loading optimization results...
                  </td>
                </tr>
              ) : filteredData.length === 0 ? (
                <tr>
                  <td colSpan="4" className="px-6 py-8 text-center text-gray-500">
                    No customers found matching that ID.
                  </td>
                </tr>
              ) : (
                filteredData.slice(0, 50).map((row, idx) => (
                  <tr key={idx} className="hover:bg-gray-50 transition-colors">
                    <td className="px-6 py-4 font-mono text-sm text-gray-900">
                      {row.customer_id}
                    </td>
                    <td className="px-6 py-4">
                      <span className="inline-flex items-center px-2.5 py-0.5 rounded-full text-xs font-medium bg-green-100 text-green-800">
                        ${row.discount} OFF
                      </span>
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-600">
                      ${row.cost}
                    </td>
                    <td className="px-6 py-4 text-sm text-gray-900 font-medium">
                      +{row.predicted_effect?.toFixed(4)}
                    </td>
                  </tr>
                ))
              )}
            </tbody>
          </table>
          
          {!loading && filteredData.length > 50 && (
            <div className="px-6 py-4 border-t border-gray-200 bg-gray-50 text-center text-sm text-gray-500">
              Showing first 50 rows of {filteredData.length.toLocaleString()} matching results.
            </div>
          )}
        </div>
      </div>
    </div>
  );
};

export default PrescriptionTable;